#include <bits/stdc++.h>
using namespace std;

int main() {
    string a, b;
    getline(cin, a);
    getline(cin, b);
    long long ca[256] = {0}, cb[256] = {0};
    for (unsigned char c : a) ca[c]++;
    for (unsigned char c : b) cb[c]++;
    // Multiset intersection takes the min count per character, union the max.
    long long inter = 0, uni = 0;
    for (int c = 0; c < 256; c++) {
        inter += min(ca[c], cb[c]);
        uni += max(ca[c], cb[c]);
    }
    printf("%.12f\n", (double)inter / uni);
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String a = br.readLine(), b = br.readLine();
        long[] ca = new long[65536], cb = new long[65536];
        for (int i = 0; i < a.length(); i++) ca[a.charAt(i)]++;
        for (int i = 0; i < b.length(); i++) cb[b.charAt(i)]++;
        // Multiset intersection takes the min count per character, union the max.
        long inter = 0, uni = 0;
        for (int c = 0; c < 65536; c++) {
            inter += Math.min(ca[c], cb[c]);
            uni += Math.max(ca[c], cb[c]);
        }
        System.out.printf("%.12f%n", (double) inter / uni);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	rd := bufio.NewReaderSize(os.Stdin, 1<<20)
	a, _ := rd.ReadString('\n')
	b, _ := rd.ReadString('\n')
	a = strings.TrimRight(a, "\r\n")
	b = strings.TrimRight(b, "\r\n")
	var ca, cb [256]int
	for i := 0; i < len(a); i++ {
		ca[a[i]]++
	}
	for i := 0; i < len(b); i++ {
		cb[b[i]]++
	}
	// Multiset intersection takes the min count per character, union the max.
	inter, uni := 0, 0
	for c := 0; c < 256; c++ {
		inter += min(ca[c], cb[c])
		uni += max(ca[c], cb[c])
	}
	fmt.Printf("%.12f\n", float64(inter)/float64(uni))
}
